<div class="dashboard-heading"><div><span class="eyebrow">ENTREGA</span><h2>Meus endereços</h2><p>Gerencie os destinos usados no checkout.</p></div><a class="button button--primary" href="<?= e(url('/minha-conta/enderecos/novo')) ?>">Novo endereço</a></div><div class="address-grid"><?php foreach($addresses as $address):?><article class="panel address-card"><?php if($address['is_default']):?><span class="badge badge--active">Principal</span><?php endif;?><h3><?= e($address['label']?:'Endereço') ?></h3><p><?= e($address['recipient_name']) ?><br><?= e($address['street']) ?>, <?= e($address['number']) ?><br><?= e($address['neighborhood']) ?> · <?= e($address['city']) ?>/<?= e($address['state']) ?><br>CEP <?= e($address['postal_code']) ?></p><div class="table-actions"><a href="<?= e(url('/minha-conta/enderecos/'.$address['id'].'/editar')) ?>">Editar</a><form method="post" action="<?= e(url('/minha-conta/enderecos/'.$address['id'])) ?>"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="link-danger">Excluir</button></form></div></article><?php endforeach;?><?php if(!$addresses):?><section class="panel"><?php $emptyTitle='Nenhum endereço cadastrado';$emptyText='Adicione um endereço para agilizar suas compras.';require dirname(__DIR__,2).'/components/dashboard/empty-state.php';?></section><?php endif;?></div>
